begin;
create table if not exists public.workshop_debriefs(date date not null references public.workshop_handover(date) on delete cascade,version integer not null,summary text,audio text,lease uuid,lease_until timestamptz,attempts integer not null default 0,created_at timestamptz not null default now(),primary key(date,version));
alter table public.workshop_debriefs enable row level security;
revoke all on public.workshop_debriefs from public,anon,authenticated;
grant all on public.workshop_debriefs to service_role;
create or replace function public.workshop_debrief_context(p_date date,p_version integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb;r public.workshop_handover%rowtype;c public.workshop_debriefs%rowtype;m boolean;begin a:=workshop_private.actor();m:=coalesce((a->>'manager')::boolean,false);if not(m or coalesce((a->>'reports_all')::boolean,false)) then raise exception 'Accès réservé aux encadrants.' using errcode='42501';end if;select * into r from public.workshop_handover where date=p_date and (m or release_at<=now());if not found then raise exception 'Récapitulatif inaccessible.' using errcode='42501';end if;if p_version is distinct from r.version then raise exception 'Récapitulatif modifié. Actualise la page.';end if;select * into c from public.workshop_debriefs where date=p_date and version=p_version;return jsonb_build_object('source',jsonb_build_object('date',r.date,'vehicles',r.vehicles,'missing_parts',r.missing_parts,'tasks',r.tasks),'summary',c.summary,'audio_available',c.audio is not null);end $$;
create or replace function public.workshop_debrief_claim(p_date date,p_version integer,p_kind text) returns uuid language plpgsql security definer set search_path='' as $$
declare c public.workshop_debriefs%rowtype;token uuid;begin if p_kind not in ('text','audio') or p_kind is null then raise exception 'Mode invalide';end if;if not exists(select 1 from public.workshop_handover where date=p_date and version=p_version) then raise exception 'Version périmée';end if;insert into public.workshop_debriefs(date,version) values(p_date,p_version) on conflict do nothing;select * into c from public.workshop_debriefs where date=p_date and version=p_version for update;if (p_kind='text' and c.summary is not null) or (p_kind='audio' and c.audio is not null) or c.lease_until>now() or c.attempts>=10 then return null;end if;if p_kind='audio' and c.summary is null then raise exception 'Débrief requis';end if;token:=gen_random_uuid();update public.workshop_debriefs set lease=token,lease_until=now()+interval '2 minutes',attempts=attempts+1 where date=p_date and version=p_version;return token;end $$;
create or replace function public.workshop_debrief_finish(p_date date,p_version integer,p_token uuid,p_kind text,p_value text) returns boolean language plpgsql security definer set search_path='' as $$
begin if p_kind not in ('text','audio') or p_kind is null or p_value is null or (p_kind='text' and length(p_value) not between 1 and 3500) or (p_kind='audio' and (length(p_value)>6000000 or p_value !~ '^[A-Za-z0-9+/]+={0,2}$')) then raise exception 'Résultat invalide';end if;if not exists(select 1 from public.workshop_handover where date=p_date and version=p_version) then return false;end if;update public.workshop_debriefs set summary=case when p_kind='text' then p_value else summary end,audio=case when p_kind='audio' then p_value else audio end,lease=null,lease_until=null where date=p_date and version=p_version and lease=p_token and lease_until>now();return found;end $$;
revoke all on function public.workshop_debrief_context(date,integer),public.workshop_debrief_claim(date,integer,text),public.workshop_debrief_finish(date,integer,uuid,text,text) from public,anon,authenticated;
grant execute on function public.workshop_debrief_context(date,integer) to authenticated;
grant execute on function public.workshop_debrief_claim(date,integer,text),public.workshop_debrief_finish(date,integer,uuid,text,text) to service_role;
notify pgrst,'reload schema';commit;
